// Regenerates public/papers/SUBS-Whitepaper.pdf from the live /whitepaper page.
//
// Usage:
//   1. Start the dev server (npm run dev)
//   2. npm run pdf:whitepaper
//      (or: node scripts/generate-whitepaper-pdf.mjs http://localhost:3005/papers/subs)
//
// Note: the SUBS PDF is generated from the web page; the GFAIP Robot Law PDF
// (public/papers/GFAIP-Robot-Law.pdf) is the original authored document and is
// not regenerated by this script.

import puppeteer from "puppeteer-core";
import { fileURLToPath } from "url";
import path from "path";
import fs from "fs";

const url = process.argv[2] ?? "http://localhost:3000/papers/subs";
const outPath = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "public",
  "papers",
  "SUBS-Whitepaper.pdf"
);

const CHROME_PATHS = [
  "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
  "/Applications/Chromium.app/Contents/MacOS/Chromium",
  "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
  "/usr/bin/google-chrome",
];
const executablePath = CHROME_PATHS.find((p) => fs.existsSync(p));
if (!executablePath) {
  console.error("No Chrome installation found — edit CHROME_PATHS in this script.");
  process.exit(1);
}

const browser = await puppeteer.launch({ executablePath, headless: "new" });
try {
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: "networkidle0", timeout: 60000 });
  await new Promise((r) => setTimeout(r, 1000));
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  await page.pdf({
    path: outPath,
    format: "A4",
    printBackground: true,
    margin: { top: "16mm", bottom: "16mm", left: "14mm", right: "14mm" },
  });
  console.log(`PDF written to ${outPath}`);
} finally {
  await browser.close();
}
